def sheet(cells: dict[str, str]) -> dict[str, int | str]:
    import re

    token_pattern = re.compile(
        r"\s*(<=|>=|<>|[A-Z][1-9][0-9]?|[A-Z]+|[0-9]+|[()+*/,:<>=-])"
    )
    precedence = {
        "=": 0, "<>": 0, "<": 0, "<=": 0, ">": 0, ">=": 0,
        "+": 1, "-": 1, "*": 2, "/": 2, "neg": 3,
    }
    cache = {}
    in_progress = set()

    def parse(text):
        tokens = token_pattern.findall(text)
        values = []
        operators = []
        expecting_operand = True
        i = 0

        def reduce_operator():
            op = operators.pop()
            if op == "neg":
                values.append(("neg", values.pop()))
            else:
                right = values.pop()
                left = values.pop()
                values.append(("binary", op, left, right))

        while i < len(tokens):
            token = tokens[i]

            if token.isdigit():
                values.append(("number", int(token)))
                expecting_operand = False

            elif token in ("SUM", "MIN", "MAX", "IF"):
                operators.append(("function", token))
                expecting_operand = True

            elif token[0].isalpha():
                if i + 2 < len(tokens) and tokens[i + 1] == ":":
                    end = tokens[i + 2]
                    col1, row1 = ord(token[0]), int(token[1:])
                    col2, row2 = ord(end[0]), int(end[1:])
                    names = []
                    for row in range(min(row1, row2), max(row1, row2) + 1):
                        for col in range(min(col1, col2), max(col1, col2) + 1):
                            name = chr(col) + str(row)
                            if name in cells:
                                names.append(("cell", name))
                    values.append(("range", names))
                    i += 2
                else:
                    values.append(("cell", token))
                expecting_operand = False

            elif token == "(":
                operators.append(["(", 0])
                expecting_operand = True

            elif token == ",":
                while not isinstance(operators[-1], list):
                    reduce_operator()
                operators[-1][1] += 1
                expecting_operand = True

            elif token == ")":
                while not isinstance(operators[-1], list):
                    reduce_operator()
                _, commas = operators.pop()
                if operators and isinstance(operators[-1], tuple):
                    _, function = operators.pop()
                    count = commas + 1
                    args = values[-count:]
                    del values[-count:]
                    if function == "IF":
                        values.append(("if", args[0], args[1], args[2]))
                    else:
                        expanded = []
                        for arg in args:
                            if arg[0] == "range":
                                expanded.extend(arg[1])
                            else:
                                expanded.append(arg)
                        values.append(("function", function, expanded))
                expecting_operand = False

            else:
                op = "neg" if token == "-" and expecting_operand else token
                while (
                    operators
                    and isinstance(operators[-1], str)
                    and (
                        precedence[operators[-1]] > precedence[op]
                        or (
                            precedence[operators[-1]] == precedence[op]
                            and op != "neg"
                        )
                    )
                ):
                    reduce_operator()
                operators.append(op)
                expecting_operand = True

            i += 1

        while operators:
            reduce_operator()
        return values[0]

    def evaluate(name):
        tasks = [("cell", name)]
        results = []

        while tasks:
            task = tasks.pop()
            kind = task[0]

            if kind == "cell":
                cell = task[1]
                if cell not in cells:
                    results.append(0)
                elif cell in cache:
                    results.append(cache[cell])
                elif cell in in_progress:
                    results.append("#CYCLE!")
                else:
                    in_progress.add(cell)
                    content = cells[cell]
                    tasks.append(("finish_cell", cell))
                    if content.startswith("="):
                        tasks.append(("eval", parse(content[1:])))
                    else:
                        results.append(int(content))

            elif kind == "finish_cell":
                cell = task[1]
                cache[cell] = results[-1]
                in_progress.remove(cell)

            elif kind == "eval":
                node = task[1]
                node_kind = node[0]

                if node_kind == "number":
                    results.append(node[1])
                elif node_kind == "cell":
                    tasks.append(("cell", node[1]))
                elif node_kind == "neg":
                    tasks.append(("neg",))
                    tasks.append(("eval", node[1]))
                elif node_kind == "binary":
                    tasks.append(("binary_left", node[1], node[3]))
                    tasks.append(("eval", node[2]))
                elif node_kind == "if":
                    tasks.append(("if", node[2], node[3]))
                    tasks.append(("eval", node[1]))
                else:
                    tasks.append(("function_next", node[1], node[2], 0, None))

            elif kind == "neg":
                value = results.pop()
                results.append(value if isinstance(value, str) else -value)

            elif kind == "binary_left":
                left = results.pop()
                if isinstance(left, str):
                    results.append(left)
                else:
                    tasks.append(("binary_right", task[1], left))
                    tasks.append(("eval", task[2]))

            elif kind == "binary_right":
                op, left = task[1], task[2]
                right = results.pop()
                if isinstance(right, str):
                    results.append(right)
                elif op == "+":
                    results.append(left + right)
                elif op == "-":
                    results.append(left - right)
                elif op == "*":
                    results.append(left * right)
                elif op == "/":
                    if right == 0:
                        results.append("#DIV/0!")
                    else:
                        quotient = abs(left) // abs(right)
                        results.append(-quotient if (left < 0) != (right < 0) else quotient)
                elif op == "=":
                    results.append(left == right)
                elif op == "<>":
                    results.append(left != right)
                elif op == "<":
                    results.append(left < right)
                elif op == "<=":
                    results.append(left <= right)
                elif op == ">":
                    results.append(left > right)
                else:
                    results.append(left >= right)

            elif kind == "if":
                condition = results.pop()
                if isinstance(condition, str):
                    results.append(condition)
                else:
                    tasks.append(("eval", task[1] if condition else task[2]))

            elif kind == "function_next":
                function, args, index, aggregate = task[1:]
                if index == len(args):
                    results.append(0 if aggregate is None else aggregate)
                else:
                    tasks.append(("function_value", function, args, index, aggregate))
                    tasks.append(("eval", args[index]))

            else:
                function, args, index, aggregate = task[1:]
                value = results.pop()
                if isinstance(value, str):
                    results.append(value)
                else:
                    if aggregate is None:
                        aggregate = value
                    elif function == "SUM":
                        aggregate += value
                    elif function == "MIN":
                        aggregate = min(aggregate, value)
                    else:
                        aggregate = max(aggregate, value)
                    tasks.append(("function_next", function, args, index + 1, aggregate))

        return results.pop()

    return {name: evaluate(name) for name in cells}
